//! Precomputed alias proofs used by coinage benchmarks.
//!
//! `generate_alias_proof` in `benchmarking.rs` first looks here; on a hit it returns the cached
//! proof instead of running ring-VRF `open` + `create`, which would otherwise take several seconds
//! per call in WASM and push the coinage benchmark suite past the CI timeout.
//!
//! Each entry is `(key, proof.encode(), alias)` where
//! `key = blake2_256(&(member, all_members, msg).encode())`. Entries are sorted by key and looked
//! up via `binary_search_by_key`.
//!
//! The table supports `RecyclerRingExponent::R2e10`, used by the coinage runtime and mock.
//! Other exponents miss the cache and require proof generation.

use hex_literal::hex;
use indiv_support::traits::RingExponent;

/// Look up a cached alias proof by computing the hash of (member, all_members, msg).
/// Returns the decoded proof and alias if found in cache.
pub fn lookup_alias_proof<M, P>(
	ring_exp: RingExponent,
	member: &M,
	all_members: &[M],
	msg: &[u8; 32],
) -> Option<(P, [u8; 32])>
where
	M: codec::Encode,
	P: codec::Decode,
{
	use codec::Encode;
	use sp_crypto_hashing::blake2_256;

	let key = blake2_256(&(member, all_members, msg).encode());
	let (proof_bytes, alias) = get_cache_entry(ring_exp, &key)?;
	let proof = P::decode(&mut &proof_bytes[..]).ok()?;
	Some((proof, alias))
}

pub fn get_cache_entry(
	ring_exp: RingExponent,
	key: &[u8; 32],
) -> Option<(&'static [u8], [u8; 32])> {
	let cache_entries = match ring_exp {
		RingExponent::R2e10 => CACHE_ENTRIES_R2E10,
		RingExponent::R2e9 | RingExponent::R2e14 => {
			log::warn!("No cache entries for ring exponent {ring_exp:?}, skipping cache lookup");
			return None;
		},
	};

	cache_entries
		.binary_search_by_key(&key, |(k, _, _)| k)
		.ok()
		.map(|i| (cache_entries[i].1, cache_entries[i].2))
}

